CREATE TABLE `org_unit`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组织编码',
  `org_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组织名称',
  `org_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组织类型: DEPARTMENT/WORKSHOP',
  `sort_no` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `is_enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_org_code`(`org_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 132 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '组织表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of org_unit
-- ----------------------------

-- ----------------------------
-- Table structure for staff_ledger
-- ----------------------------
DROP TABLE IF EXISTS `staff_ledger`;
CREATE TABLE `staff_ledger`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_unit_id` bigint NOT NULL COMMENT '车间ID',
  `ledger_month` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '台账月份(YYYY-MM)',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态',
  `in_work_count` int NULL DEFAULT NULL COMMENT '在岗人数',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注',
  `change_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '变动说明',
  `director_user_id` bigint NULL DEFAULT NULL COMMENT '审批主任ID',
  `director_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '主任审批意见',
  `director_approved_at` datetime NULL DEFAULT NULL COMMENT '主任审批时间',
  `hr_user_id` bigint NULL DEFAULT NULL COMMENT '审核人事科ID',
  `hr_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '人事科审核意见',
  `hr_approved_at` datetime NULL DEFAULT NULL COMMENT '人事科审核时间',
  `submitted_at` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `created_by` bigint NOT NULL COMMENT '创建人ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_org_month`(`org_unit_id` ASC, `ledger_month` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_ledger_month`(`ledger_month` ASC) USING BTREE,
  CONSTRAINT `fk_staff_ledger_org_unit` FOREIGN KEY (`org_unit_id`) REFERENCES `org_unit` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '现员分布台账' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of staff_ledger
-- ----------------------------

-- ----------------------------
-- Table structure for staff_ledger_detail
-- ----------------------------
DROP TABLE IF EXISTS `staff_ledger_detail`;
CREATE TABLE `staff_ledger_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ledger_id` bigint NOT NULL COMMENT '台账ID',
  `employee_basic_id` bigint NULL DEFAULT NULL COMMENT '基础表ID',
  `station_point` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '岗点',
  `team_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班组',
  `shift_category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班别（日勤/甲班/乙班/丙班/丁班/预备/其他）',
  `work_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '岗位',
  `sort_no` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `jia_ban1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '甲班1',
  `jia_ban2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '甲班2',
  `yi_ban1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '乙班1',
  `yi_ban2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '乙班2',
  `bing_ban1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '丙班1',
  `bing_ban2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '丙班2',
  `ding_ban1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '丁班1',
  `ding_ban2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '丁班2',
  `yu_bei1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预备1',
  `yu_bei2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预备2',
  `daily_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '日勤姓名',
  `identity_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '职务',
  `extra_shift_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '额外班次JSON数据',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ledger_id`(`ledger_id` ASC) USING BTREE,
  INDEX `idx_employee_basic_id`(`employee_basic_id` ASC) USING BTREE,
  CONSTRAINT `fk_detail_employee` FOREIGN KEY (`employee_basic_id`) REFERENCES `employee_basic` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_detail_ledger` FOREIGN KEY (`ledger_id`) REFERENCES `staff_ledger` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 75 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '台账明细' ROW_FORMAT = DYNAMIC;

